sysdrills/09-queues-and-backlog/01-queue.solution:
export function queueWaitSec(jobsAhead, workers, jobSec) {
  return (jobsAhead * jobSec) / workers;
}

export function jobEtaSec(jobsAhead, workers, jobSec) {
  return queueWaitSec(jobsAhead, workers, jobSec) + jobSec;
}

