sysdrills/09-queues-and-backlog/02-backl.solution:
export function maxHealthyBacklog(processPerSec, slaSec) {
  return processPerSec * slaSec;
}

export function jobsOverSla(backlog, processPerSec, slaSec) {
  return Math.max(0, backlog - processPerSec * slaSec);
}

