sysdrills/09-queues-and-backlog/03-consu.solution:
export function consumersToDrain(backlog, drainSec, arrivePerSec, perConsumerPerSec) {
  return Math.ceil((backlog + arrivePerSec * drainSec) / (drainSec * perConsumerPerSec));
}

export function surplusPerSec(consumers, perConsumerPerSec, arrivePerSec) {
  return consumers * perConsumerPerSec - arrivePerSec;
}

