sysdrills/09-queues-and-backlog/04-retry.solution:
export function attemptsPerUserRequest(attemptsPerCall, depth) {
  let amp = 1;
  for (let i = 0; i < depth; i++) amp *= attemptsPerCall;
  return amp;
}

export function bottomLayerQps(baseQps, attemptsPerCall, depth) {
  return baseQps * attemptsPerUserRequest(attemptsPerCall, depth);
}

