sysdrills/09-queues-and-backlog/08-load-.solution:
export function shedPerSec(arrivePerSec, capacityPerSec) {
  return Math.max(0, arrivePerSec - capacityPerSec);
}

export function shedPermille(arrivePerSec, capacityPerSec) {
  return (shedPerSec(arrivePerSec, capacityPerSec) * 1000) / arrivePerSec;
}
